package android.widget;
public class ViewSwitcher extends ViewAnimator { public ViewSwitcher(android.content.Context c) { super(c); } public ViewSwitcher(android.content.Context c,android.util.AttributeSet a) { super(c,a); } public ViewSwitcher(android.content.Context c,android.util.AttributeSet a,int s) { super(c,a,s); } public ViewSwitcher(android.content.Context c,android.util.AttributeSet a,int s,int r) { super(c,a,s,r); } public interface ViewFactory { android.view.View makeView(); } public void setFactory(ViewFactory factory) { addView(factory.makeView()); addView(factory.makeView()); } public android.view.View getCurrentView() { return getChildAt(getDisplayedChild()); } public android.view.View getNextView() { return getChildAt((getDisplayedChild()+1)%2); } }
